const T2=(es,en)=>({es,en});
const CHIPS=[{id:"chipA",l:T2("Trabajo y proyectos","Work & projects")},{id:"chipB",l:T2("Tareas del día a día","Everyday tasks")},{id:"chipC",l:T2("Investigar y aprender","Research & learning")},{id:"chipD",l:T2("Otra cosa","Something else")}];
/* creating a bot = a conversation: + menu → what for (chips) → job in one paragraph → test run → name + avatar */
function mkCreate(o){const ch=CHIPS.find(c=>c.id==o.chip);return [
 {k:"click",pre:"newBot",preFx:"openMenu",t:"mkBot",fx:"startSetup",cap:T2("Toca «+» y elige «Crear un bot nuevo».","Tap \"+\" and choose \"Create new Bot\"."),w:T2("Crear un bot es una conversación: el bot te hace preguntas.","Creating a bot is a conversation: it asks you questions."),s:T2("Arriba, junto a tus bots, hay un botón «+». Tócalo. Se abre un menú pequeño: toca «Crear un bot nuevo».","Next to your bots there is a \"+\" button. Tap it. A small menu opens: tap \"Create new Bot\".")},
 {k:"click",t:o.chip,fx:"say",done:T2("Elegiste: "+ch.l.es,"You chose: "+ch.l.en),say:T2("Muy bien. Ahora cuéntame su trabajo en un párrafo, con palabras simples.","Great. Now tell me its job in one paragraph, in plain words."),cap:T2("Dile para qué es.","Tell it what it's for."),w:T2("Toca la opción que más se parece. No hay respuesta equivocada.","Tap the option that fits best. There's no wrong answer."),s:T2("El bot te muestra unas opciones. Toca «"+ch.l.es+"».","The bot shows a few options. Tap \""+ch.l.en+"\".")},
 {k:"type",go:"send",fx:"send",f:[{t:"msg",v:o.job}],reply:T2("Hice una prueba rápida para que veas cómo quedaría:","I did a quick test run so you can see how it would look:"),card:{i:"play",h:T2("Prueba","Test run"),l:o.test},after:T2("¿Te sirve así? Si sí, ¿cómo se llamará tu bot?","Does that work? If so, what should we call your bot?"),cap:T2("Describe su trabajo en un párrafo.","Describe its job in one paragraph."),w:T2("Palabras simples, un párrafo, sin formato. Enseguida hace una prueba.","Plain words, one paragraph, no formatting. It does a test run right away."),s:T2("Escribe qué debe hacer tu bot, como se lo dirías a una persona. Un solo párrafo. Puedes usar el texto de arriba o «Escribirlo por mí». Luego toca la flecha.","Write what your bot should do, the way you'd tell a person. One paragraph. You can use the text above or \"Type it for me\". Then tap the arrow.")},
 {k:"type",go:"send",fx:"nameBot",f:[{t:"msg",v:o.name}],reply:T2("¡Listo! Ya existo: me llamo {n}. Si quieres cambiar algo, como el horario, solo pídemelo aquí.","Done! I'm ready: my name is {n}. If you want to change anything, like the schedule, just ask me here."),cap:T2("Ponle un nombre.","Give it a name."),w:T2("El nombre dice para qué es. Recibe su propia imagen.","The name says what it's for. It gets its own picture."),s:T2("Escribe el nombre de tu bot en la caja y toca la flecha. Aparecerá en la lista de la izquierda con su imagen.","Type your bot's name in the box and tap the arrow. It will appear in the list with its picture.")}]}
const LESSONS={
m1:{bots:[{n:"Asistente",c:""}],
 idea:{type:"compare",es:{h:"¿Respuesta rápida o un bot que recuerda?",a:["chat","Un chat","Haces una pregunta y te responde. Sirve cuando solo necesitas una respuesta ahora."],b:["bot","Un bot","Tiene nombre y un trabajo. Recuerda lo que le dijiste y puede guardar cosas para después."],note:"Hoy vas a crear un bot llamado «Resumen claro». Lo crearás conversando con él. Después le darás una noticia y lo guardará para mañana."},
  en:{h:"A quick answer, or a bot that remembers?",a:["chat","A chat","You ask a question and it answers. Good when you only need an answer now."],b:["bot","A bot","It has a name and a job. It remembers what you told it and can keep things for later."],note:"Today you'll create a bot called \"Resumen claro\". You'll create it by chatting. Then you'll give it a news item and it will keep it for tomorrow."},
  s:T2("Un chat contesta y se olvida. Un bot tiene nombre, recuerda y guarda cosas para ti.","A chat answers and forgets. A bot has a name, remembers, and keeps things for you.")},
 steps:[...mkCreate({chip:"chipC",job:T2("Quiero un bot que me resuma noticias en español, corto, en 5 líneas: qué pasó, por qué importa y qué no se sabe. Nunca envía nada a nadie.","I want a bot that summarizes news for me, short, in 5 lines: what happened, why it matters, and what is unknown. It never sends anything to anyone."),
  test:T2(["Noticia de ejemplo: abre una biblioteca nueva.","Qué pasó: la ciudad abre una biblioteca el sábado.","Qué no se sabe: el horario."],["Sample news: a new library opens.","What happened: the city opens a library on Saturday.","Unknown: the opening hours."]),name:T2("Resumen claro","Resumen claro")}),
 {k:"type",f:[{t:"msg",v:T2("Resume esta noticia en 5 líneas: qué pasó, por qué importa, qué no se sabe. Sin consejos. Noticia: «La ciudad aprobó un nuevo horario de autobuses que empieza el lunes».","Summarize this news in 5 lines: what happened, why it matters, what is unknown. No advice. News: \"The city approved a new bus schedule starting Monday\".")}],go:"send",fx:"send",reply:T2("1. Qué pasó: la ciudad aprobó un nuevo horario de autobuses.\n2. Desde cuándo: empieza el lunes.\n3. Por qué importa: algunas rutas pueden pasar con menos frecuencia.\n4. Qué no se sabe: si cambian los fines de semana.\n5. Qué no se sabe: cuánto cuesta el cambio.","1. What happened: the city approved a new bus schedule.\n2. Since when: it starts Monday.\n3. Why it matters: some routes may run less often.\n4. Unknown: whether weekends change.\n5. Unknown: how much the change costs."),cap:T2("Pídele el resumen de una noticia.","Ask for a summary of a news item."),w:T2("Le dices qué hacer y le das la noticia.","You tell it what to do and give it the news."),s:T2("Ahora le hablas al bot. Escribe en la caja de abajo lo que quieres (puede ser el texto de arriba o algo parecido), o toca «Escribirlo por mí». Luego toca la flecha para enviarlo. No se envía nada a nadie más.","Now you talk to the bot. Type what you want in the box at the bottom (the text above or something similar), or tap \"Type it for me\". Then tap the arrow to send it. Nothing goes to anyone else.")},
 {k:"type",f:[{t:"msg",v:T2("Guarda este resumen para mañana.","Keep this summary for tomorrow.")}],go:"send",fx:"send",reply:T2("Listo. Guardé el resumen. Mañana me lo puedes pedir con «¿qué guardaste ayer?».","Done. I kept the summary. Tomorrow you can ask me \"what did you keep yesterday?\"."),cap:T2("Pídele que lo guarde.","Ask it to keep it."),w:T2("Esto es lo que un chat no hace: guardar para después.","This is what a chat doesn't do: keep it for later."),s:T2("Un bot puede guardar cosas para ti. Solo se lo pides con una frase y tocas la flecha.","A bot can keep things for you. Just ask in one sentence and tap the arrow.")}],
 real:T2(["Abre tu Grok Bot.","Toca «+» y luego «Crear un bot nuevo».","Elige una opción y describe su trabajo en un párrafo. Mira la prueba que hace.","Llámalo «Resumen claro».","Envía la instrucción con una noticia corta.","Pídele: «Guarda este resumen para mañana».","Lee la respuesta y llena tu diario abajo."],["Open your Grok Bot.","Tap \"+\" then \"Create new Bot\".","Pick an option and describe its job in one paragraph. Look at its test run.","Name it \"Resumen claro\".","Send the instruction with a short news item.","Ask: \"Keep this summary for tomorrow\".","Read the answer and fill in your journal below."])},
m2:{bots:[{n:"Asistente",c:""},{n:"Resumen claro",c:"g"}],
 idea:{type:"parts",es:{h:"Una buena instrucción tiene 4 partes",p:[["target","Objetivo","Qué quieres."],["users","Contexto","Para quién o por qué."],["list","Formato","Cómo lo quieres: corto, en lista…"],["x","Qué no hacer","Lo que debe evitar."]],note:"Ejemplo de hoy: «Explícamelo como si se lo contara a mi hija», en formato corto. Consejo: palabras simples, un párrafo, sin formato."},
  en:{h:"A good instruction has 4 parts",p:[["target","Goal","What you want."],["users","Context","Who it's for, or why."],["list","Format","How you want it: short, a list…"],["x","What not to do","What it should avoid."]],note:"Today's example: \"Explain it as if I were telling my daughter\", in a short format. Tip: plain words, one paragraph, no formatting."},
  s:T2("Dile al bot qué quieres, para quién es, cómo lo quieres y qué no debe hacer. Cuatro frases cortas.","Tell the bot what you want, who it's for, how you want it, and what not to do. Four short sentences.")},
 steps:[
 {k:"click",t:"bot-1",fx:"selectBot",arg:1,cap:T2("Abre tu bot «Resumen claro».","Open your bot \"Resumen claro\"."),w:T2("Usamos el bot que creaste en el Módulo 1.","We use the bot you made in Module 1."),s:T2("A la izquierda está el bot que creaste en el Módulo 1. Tócalo para abrirlo.","On the left is the bot you made in Module 1. Tap it to open it.")},
 {k:"type",f:[{t:"msg",v:T2("Objetivo: explícame qué es la inflación.\nContexto: explícamelo como si se lo contara a mi hija de 12 años.\nFormato: máximo 4 frases cortas.\nNo hagas: sin palabras técnicas y sin consejos de dinero.","Goal: explain what inflation is.\nContext: explain it as if I were telling my 12-year-old daughter.\nFormat: at most 4 short sentences.\nDon't: no technical words and no money advice.")}],go:"send",fx:"send",reply:T2("La inflación es cuando las cosas cuestan más con el tiempo.\nCon el mismo dinero compras un poco menos.\nEl pan que antes costaba 10, después cuesta 11.\nPasa despacio, por eso a veces no lo notamos.","Inflation is when things cost more over time.\nWith the same money you buy a little less.\nBread that cost 10 later costs 11.\nIt happens slowly, so sometimes we don't notice."),cap:T2("Escribe una instrucción con las 4 partes.","Write an instruction with the 4 parts."),w:T2("Objetivo, contexto, formato y qué no hacer: una por línea.","Goal, context, format, and what not to do: one per line."),s:T2("Son 4 frases cortas: qué quieres, para quién es, qué tan largo y qué evitar. Toca «Escribirlo por mí» si no quieres escribir tanto. Luego toca la flecha.","It's 4 short sentences: what you want, who it's for, how long, and what to avoid. Tap \"Type it for me\" if you'd rather not type it all. Then tap the arrow.")}],
 real:T2(["Abre tu bot «Resumen claro».","Escribe un objetivo: algo que quieras entender.","Agrega el contexto: «explícamelo como si se lo contara a mi hija».","Agrega el formato: «máximo 4 frases cortas».","Agrega qué no hacer, y envía.","Lee la respuesta y llena tu diario abajo."],["Open your bot \"Resumen claro\".","Write a goal: something you want to understand.","Add the context: \"explain it as if I were telling my daughter\".","Add the format: \"at most 4 short sentences\".","Add what not to do, and send.","Read the answer and fill in your journal below."])}};

/* ---------- Modules 3–8 ---------- */
MODS.forEach(m=>m.built=1);
const BOTS3=[{n:"Asistente",c:""},{n:"Resumen claro",c:"g"}];
const BOTS5=[{n:"Asistente",c:""},{n:"Resumen claro",c:"g"},{n:"Cita",c:"o"}];
const pick=(i,es,en,wes,wen,ses,sen)=>({k:"click",t:"bot-"+i,fx:"selectBot",arg:i,cap:T2(es,en),w:T2(wes,wen),s:T2(ses,sen)});
const pickRC=()=>pick(1,"Abre tu bot «Resumen claro».","Open your bot \"Resumen claro\".","Es el bot que ya conoces.","It's the bot you already know.","A la izquierda está «Resumen claro». Tócalo una vez para abrirlo.","On the left is \"Resumen claro\". Tap it once to open it.");
const pickCita=()=>pick(2,"Abre el bot «Cita».","Open the bot \"Cita\".","Es un bot para ayudarte con citas y recordatorios.","It's a bot that helps with appointments and reminders.","A la izquierda está el bot «Cita». Tócalo una vez para abrirlo.","On the left is the bot \"Cita\". Tap it once to open it.");
const say=(ves,ven,o)=>Object.assign({k:"type",go:"send",fx:"send",f:[{t:"msg",v:T2(ves,ven)}]},o);
Object.assign(LESSONS,{
m3:{bots:BOTS3,
 idea:{type:"compare",es:{h:"Tu bot puede recordar lo que le pides",a:["brain","Recordar","Le pides que recuerde una preferencia. La usará la próxima vez, sin que la repitas."],b:["pen","Cambiar y borrar","Si cambias de idea, se lo dices. Y le pides que borre lo viejo."],note:"Hoy le pedirás a «Resumen claro» que recuerde cómo quieres tus resúmenes. Después lo cambiarás."},
  en:{h:"Your bot can remember what you ask",a:["brain","Remember","You ask it to remember a preference. It uses it next time, without you repeating it."],b:["pen","Change and delete","If you change your mind, you tell it. And you ask it to delete the old one."],note:"Today you'll ask \"Resumen claro\" to remember how you like your summaries. Then you'll change it."},
  s:T2("El bot puede guardar una preferencia tuya, como una nota. Tú puedes cambiarla o borrarla cuando quieras.","The bot can keep a preference of yours, like a note. You can change or delete it anytime.")},
 steps:[pickRC(),
  say("Recuerda esto: mis resúmenes van en español, 5 líneas, sin consejos.","Remember this: my summaries are in Spanish, 5 lines, no advice.",{reply:T2("Entendido. Lo voy a recordar.","Understood. I'll remember it."),card:{i:"brain",h:T2("Recuerdo guardado","Memory saved"),l:T2(["Resúmenes: en español, 5 líneas, sin consejos."],["Summaries: in Spanish, 5 lines, no advice."])},
   cap:T2("Pídele que recuerde tu preferencia.","Ask it to remember your preference."),w:T2("Así no tienes que repetirlo cada vez.","That way you don't have to repeat it every time."),s:T2("Dile al bot cómo te gustan los resúmenes y que lo recuerde. Luego toca la flecha.","Tell the bot how you like summaries and to remember it. Then tap the arrow.")}),
  say("Cambia eso: ahora quiero 3 líneas. Borra la regla de 5 líneas. ¿Qué recuerdas ahora?","Change that: now I want 3 lines. Delete the 5-line rule. What do you remember now?",{reply:T2("Listo. Borré la regla de 5 líneas. Esto es lo que recuerdo ahora:","Done. I deleted the 5-line rule. This is what I remember now:"),card:{i:"brain",h:T2("Lo que recuerdo","What I remember"),l:T2(["Resúmenes: en español, 3 líneas, sin consejos."],["Summaries: in Spanish, 3 lines, no advice."])},
   cap:T2("Cámbiala y pregunta qué quedó.","Change it and ask what's left."),w:T2("Así compruebas que borró lo viejo.","That way you check it deleted the old one."),s:T2("Pide el cambio, pide que borre lo viejo y pregunta qué recuerda. Todo en un mensaje.","Ask for the change, ask it to delete the old one, and ask what it remembers. All in one message.")})],
 real:T2(["Abre tu bot «Resumen claro».","Pídele que recuerde: «mis resúmenes van en español, 5 líneas, sin consejos».","Lee cómo te confirma lo que recordó.","Pídele que cambie a 3 líneas y que borre la regla vieja.","Pregunta «¿Qué recuerdas ahora?» y llena tu diario."],["Open your bot \"Resumen claro\".","Ask it to remember: \"my summaries are in Spanish, 5 lines, no advice\".","Read how it confirms what it remembered.","Ask it to change to 3 lines and delete the old rule.","Ask \"What do you remember now?\" and fill in your journal."])},
m4:{bots:BOTS3,
 idea:{type:"compare",es:{h:"Que el bot trabaje solo, a una hora fija",a:["star","Una habilidad","Es un proceso guardado con un nombre, para usarlo otra vez."],b:["clock","Una rutina","Hace esa habilidad sola, a una hora fija, aunque no estés."],note:"Hoy guardarás tu resumen como habilidad y harás que corra solo de lunes a viernes a las 8:00 a. m."},
  en:{h:"Let the bot work on its own, on a schedule",a:["star","A skill","A saved process with a name, so you can use it again."],b:["clock","A routine","It runs that skill on its own, at a set time, even when you're away."],note:"Today you'll save your summary as a skill and make it run by itself on weekdays at 8:00 AM."},
  s:T2("Primero le das un nombre a lo que el bot sabe hacer. Después le dices a qué hora hacerlo, solo.","First you give a name to what the bot knows how to do. Then you tell it what time to do it, on its own.")},
 steps:[pickRC(),
  say("Guarda este proceso como una habilidad llamada «Práctica — Resumen en 3 líneas».","Save this process as a skill named \"Práctica — Resumen en 3 líneas\".",{reply:T2("Hecho. Guardé la habilidad.","Done. I saved the skill."),card:{i:"star",h:T2("Habilidad guardada","Skill saved"),l:T2(["Nombre: Práctica — Resumen en 3 líneas","Hace: resumen en español, 3 líneas, sin consejos."],["Name: Práctica — Resumen en 3 líneas","Does: summary in Spanish, 3 lines, no advice."])},
   cap:T2("Guarda el proceso como habilidad.","Save the process as a skill."),w:T2("Con un nombre, el bot sabe qué hacer después.","With a name, the bot knows what to do later."),s:T2("Le pides al bot que guarde lo que hace, con un nombre fácil de recordar.","You ask the bot to save what it does, with a name that's easy to remember.")}),
  say("Crea una rutina: cada mañana usa esa habilidad. Publica el resultado aquí. No envíes correos.","Create a routine: every morning, use that skill. Post the result here. Don't send emails.",{reply:T2("Listo. Creé la rutina. ¿Quieres cambiar algo del horario?","Done. I created the routine. Want to change anything about the schedule?"),card:{i:"clock",h:T2("Rutina: Práctica — Resumen en 3 líneas","Routine: Práctica — Resumen en 3 líneas"),l:T2(["Cuándo: todos los días, 9:00 a. m.","Dónde: aquí, en este chat","Correos: ninguno"],["When: every day, 9:00 AM","Where: here, in this chat","Emails: none"])},
   cap:T2("Crea la rutina.","Create the routine."),w:T2("Así el bot lo hace solo, aunque no estés.","That way the bot does it alone, even when you're away."),s:T2("Pide la rutina, dónde publicar y qué no hacer. Luego toca la flecha.","Ask for the routine, where to post, and what not to do. Then tap the arrow.")}),
  say("Cámbiala a días laborables a las 8:00 a. m., hora del Este.","Change it to weekdays at 8:00 AM Eastern.",{reply:T2("Hecho. Cambié el horario. Si algún día no corre, no se rompió nada: me lo dices y lo revisamos.","Done. I changed the schedule. If one day it doesn't run, nothing broke: tell me and we'll check it."),card:{i:"clock",h:T2("Rutina actualizada","Routine updated"),l:T2(["Cuándo: lunes a viernes, 8:00 a. m. (hora del Este)","Próxima vez: mañana, 8:00 a. m.","Dónde: aquí · Correos: ninguno"],["When: weekdays, 8:00 AM (Eastern)","Next run: tomorrow, 8:00 AM","Where: here · Emails: none"])},
   cap:T2("Cambia el horario pidiéndolo en el chat.","Change the schedule by asking in chat."),w:T2("No hay que buscar menús: lo pides con una frase.","No menus to hunt for: you ask in one sentence."),s:T2("Si el horario no te sirve, se lo dices al bot con palabras simples: qué días y a qué hora.","If the schedule doesn't suit you, tell the bot in plain words: which days and what time.")})],
 real:T2(["Abre tu bot «Resumen claro».","Pídele guardar el proceso como habilidad «Práctica — Resumen en 3 líneas».","Pídele una rutina que publique aquí, sin correos.","Cambia el horario en el chat: «cámbiala a días laborables a las 8:00 a. m., hora del Este».","Lee la confirmación: días, hora y próxima vez.","Mañana revisa si corrió. Si no corrió, no se rompió nada."],["Open your bot \"Resumen claro\".","Ask it to save the process as the skill \"Práctica — Resumen en 3 líneas\".","Ask for a routine that posts here, no emails.","Change the schedule in chat: \"change it to weekdays at 8:00 AM Eastern\".","Read the confirmation: days, time, and next run.","Tomorrow, check whether it ran. If it didn't, nothing broke."])},
m5:{bots:BOTS3,
 idea:{type:"compare",es:{h:"Correo y calendario: solo con tu permiso",a:["lock","Sin conexión","El bot no ve tu calendario. Si no lo ve, debe decírtelo y no inventar."],b:["plug","Con permiso","Tú decides conectarlo. Antes, el bot te explica qué podrá ver y qué no."],note:"Hoy crearás el bot «Cita» conversando con él. Luego lo usarás: primero sin calendario, después con permiso, y al final un borrador de recordatorio."},
  en:{h:"Email and calendar: only with your permission",a:["lock","Not connected","The bot can't see your calendar. If it can't see it, it should say so and not make things up."],b:["plug","With permission","You decide to connect it. First, the bot explains what it will and won't see."],note:"Today you'll create the bot \"Cita\" by chatting with it. Then you'll use it: first without the calendar, then with permission, and finally a reminder draft."},
  s:T2("El bot no ve tus cosas hasta que tú le das permiso. Y antes de pedirlo, te explica qué podrá hacer.","The bot can't see your things until you give permission. And before asking, it explains what it will be able to do.")},
 steps:[...mkCreate({chip:"chipB",job:T2("Quiero un bot que me ayude con mis citas médicas y recordatorios. Nunca agrega, cambia ni borra nada en mi calendario sin preguntarme.","I want a bot that helps me with my medical appointments and reminders. It never adds, changes, or deletes anything on my calendar without asking me."),
  test:T2(["Recordatorio de ejemplo: jueves 10:00 a. m., dentista.","Es solo un borrador: no agregué nada."],["Sample reminder: Thursday 10:00 AM, dentist.","It's only a draft: I didn't add anything."]),name:T2("Cita","Cita")}),
  say("¿Qué tengo mañana en mi calendario?","What do I have on my calendar tomorrow?",{reply:T2("Todavía no puedo ver tu calendario, así que no voy a inventar nada. Si quieres, puedes conectarlo. Antes, mira lo que podré y no podré hacer:","I can't see your calendar yet, so I won't make anything up. If you want, you can connect it. First, here is what I will and won't do:"),card:{i:"plug",h:T2("Conectar calendario","Connect calendar"),l:T2(["Podré: leer tus eventos para responderte.","No haré: agregar, cambiar ni borrar eventos sin tu confirmación.","Puedes desconectarlo cuando quieras."],["I will: read your events to answer you.","I won't: add, change, or delete events without your confirmation.","You can disconnect it anytime."]),b:[{id:"perm",l:T2("Conectar calendario","Connect calendar")}]},
   cap:T2("Pregunta por tu calendario.","Ask about your calendar."),w:T2("Sin conexión, el bot debe decir que no lo ve.","Without a connection, the bot should say it can't see it."),s:T2("Pregunta qué tienes mañana. Fíjate: el bot no inventa, te explica el permiso primero.","Ask what you have tomorrow. Notice: the bot doesn't make things up; it explains the permission first.")}),
  {k:"click",t:"perm",fx:"say",done:T2("Calendario conectado","Calendar connected"),say:T2("Gracias. Ya puedo ver tu calendario. Mañana tienes: 10:00 a. m., control con la doctora.","Thank you. I can see your calendar now. Tomorrow you have: 10:00 AM, check-up with the doctor."),
   cap:T2("Lee el permiso y conecta el calendario.","Read the permission and connect the calendar."),w:T2("Tú decides. Ya leíste qué podrá ver y qué no.","You decide. You've read what it will and won't see."),s:T2("Lee la tarjeta: dice qué podrá hacer el bot. Si estás de acuerdo, toca «Conectar calendario». Es una práctica: nada es real.","Read the card: it says what the bot will be able to do. If you agree, tap \"Connect calendar\". It's practice: nothing is real.")},
  say("Escribe un borrador de recordatorio de 4 líneas para esa cita. No lo agregues al calendario.","Write a 4-line reminder draft for that appointment. Don't add it to the calendar.",{reply:T2("Aquí está el borrador. No lo agregué a tu calendario: queda esperando tu decisión.","Here is the draft. I didn't add it to your calendar: it's waiting for your decision."),card:{i:"pen",h:T2("Borrador (no agregado)","Draft (not added)"),l:T2(["Mañana 10:00 a. m.: control con la doctora.","Llevar la tarjeta del seguro.","Salir de casa a las 9:15.","Anotar preguntas antes de ir."],["Tomorrow 10:00 AM: check-up with the doctor.","Bring the insurance card.","Leave home at 9:15.","Write down questions before going."])},
   cap:T2("Pide un borrador, sin agregarlo.","Ask for a draft, without adding it."),w:T2("El bot lo muestra y espera. Tú decides.","The bot shows it and waits. You decide."),s:T2("Pide el recordatorio y di claramente que no lo agregue. El bot solo te lo muestra.","Ask for the reminder and say clearly not to add it. The bot only shows it to you.")})],
 real:T2(["Toca «+», «Crear un bot nuevo», describe su trabajo y llámalo «Cita».","Pregúntale qué tienes mañana. Si no ve tu calendario, debe decirlo sin inventar.","Si tu Grok Bot te ofrece conectar el calendario, lee qué podrá ver antes de aceptar.","Pide un borrador de recordatorio de 4 líneas y di que no lo agregue.","Lee el borrador y llena tu diario."],["Tap \"+\", \"Create new Bot\", describe its job, and name it \"Cita\".","Ask what you have tomorrow. If it can't see your calendar, it should say so without making things up.","If your Grok Bot offers to connect the calendar, read what it will see before accepting.","Ask for a 4-line reminder draft and say not to add it.","Read the draft and fill in your journal."])},
m6:{bots:BOTS3,
 idea:{type:"compare",es:{h:"Revisar y corregir es normal",a:["search","Revisa","Lee la respuesta. ¿Es lo que pediste? ¿Es muy larga?"],b:["pen","Corrige una cosa","Cambia una sola línea de tu instrucción y vuelve a enviar."],note:"Hoy el resumen saldrá demasiado largo. Lo vas a corregir con una sola frase."},
  en:{h:"Checking and correcting is normal",a:["search","Check","Read the answer. Is it what you asked for? Is it too long?"],b:["pen","Fix one thing","Change just one line of your instruction and send again."],note:"Today the summary will come out too long. You'll fix it with a single sentence."},
  s:T2("Si la respuesta no te sirve, no empieces de cero. Cambia una cosa y vuelve a pedir.","If the answer doesn't help, don't start over. Change one thing and ask again.")},
 steps:[pickRC(),
  say("Resume esta noticia: «La ciudad aprobó un nuevo horario de autobuses que empieza el lunes».","Summarize this news: \"The city approved a new bus schedule starting Monday\".",{reply:T2("La ciudad aprobó un nuevo horario de autobuses. El cambio empieza el lunes. Varias rutas cambian de hora. Algunas pasarán con menos frecuencia. Otras tendrán paradas nuevas. La ciudad dice que busca ordenar el servicio. Algunos vecinos están preocupados. Todavía no se sabe si cambian los fines de semana. Tampoco se sabe cuánto cuesta el cambio.","The city approved a new bus schedule. The change starts Monday. Several routes change times. Some will run less often. Others will have new stops. The city says it wants to organize the service. Some neighbors are worried. It's not yet known whether weekends change. Nor is it known how much the change costs."),
   cap:T2("Pide un resumen y revisa el largo.","Ask for a summary and check the length."),w:T2("Esta vez saldrá demasiado largo, a propósito.","This time it will come out too long, on purpose."),s:T2("Pide el resumen. Cuando llegue, fíjate: es muy largo. En el próximo paso lo arreglas.","Ask for the summary. When it arrives, notice: it's very long. In the next step you'll fix it.")}),
  say("Cambia una cosa: máximo 3 líneas cortas. Hazlo otra vez.","Change one thing: at most 3 short lines. Do it again.",{reply:T2("1. Nuevo horario de autobuses desde el lunes.\n2. Algunas rutas pasarán menos seguido.\n3. No se sabe si cambian los fines de semana.","1. New bus schedule from Monday.\n2. Some routes will run less often.\n3. Unknown whether weekends change."),
   cap:T2("Corrige una línea y vuelve a enviar.","Fix one line and send again."),w:T2("Una sola corrección basta.","One correction is enough."),s:T2("Dile solo lo que quieres cambiar, por ejemplo el largo. El bot rehace el resumen.","Tell it only what you want to change, for example the length. The bot redoes the summary.")})],
 real:T2(["Abre tu bot «Resumen claro».","Pide un resumen de una noticia.","Revisa: ¿es muy largo? ¿falta algo?","Cambia una sola cosa, por ejemplo «máximo 3 líneas cortas», y envía.","Compara las dos respuestas y llena tu diario."],["Open your bot \"Resumen claro\".","Ask for a summary of a news item.","Check: is it too long? Is something missing?","Change just one thing, for example \"at most 3 short lines\", and send.","Compare the two answers and fill in your journal."])},
m7:{bots:BOTS5,
 idea:{type:"compare",es:{h:"Reglas simples que te protegen",a:["shield","Nunca","Nunca pegues contraseñas. Nunca confirmes pagos desde un bot."],b:["help","Si falta algo, que pregunte","Un buen bot pregunta un dato a la vez, en vez de inventar."],note:"Los engaños existen. No es para asustarse: con estas reglas simples estás protegido, y el bot te pide confirmación antes de actuar."},
  en:{h:"Simple rules that protect you",a:["shield","Never","Never paste passwords. Never confirm payments through a bot."],b:["help","If something's missing, it asks","A good bot asks for one detail at a time instead of making things up."],note:"Scams exist. There's no need to be scared: with these simple rules you're protected, and the bot asks for confirmation before acting."},
  s:T2("Tres reglas: nada de contraseñas, nada de pagos, y si falta un dato, el bot pregunta. Antes de hacer algo, te pide permiso.","Three rules: no passwords, no payments, and if a detail is missing, the bot asks. Before doing anything, it asks permission.")},
 steps:[pickCita(),
  say("Ayúdame a pedir una cita médica.","Help me request a medical appointment.",{reply:T2("Con gusto. Me falta un dato: ¿con qué médico o especialidad es?","Happy to. I'm missing one detail: which doctor or specialty is it with?"),
   cap:T2("Pide algo incompleto.","Ask for something incomplete."),w:T2("El bot pregunta un solo dato que falta.","The bot asks for one missing detail."),s:T2("Pide la cita sin dar detalles. Fíjate: el bot no inventa, pregunta una cosa a la vez.","Ask for the appointment without details. Notice: the bot doesn't invent; it asks one thing at a time.")}),
  say("Con la doctora de cabecera. Y paga la consulta con mi tarjeta.","With my family doctor. And pay for the visit with my card.",{reply:T2("Gracias. Sobre el pago: no hago pagos ni los confirmo. Y nunca pegues contraseñas ni números de tarjeta en un chat. Sí puedo preparar el texto para pedir la cita, pero solo si me lo confirmas.","Thank you. About the payment: I don't make or confirm payments. And never paste passwords or card numbers in a chat. I can prepare the text to request the appointment, but only if you confirm."),card:{i:"shield",h:T2("Necesita tu confirmación","Needs your confirmation"),l:T2(["Acción: preparar el texto para pedir la cita.","No se envía nada sin tu sí."],["Action: prepare the text to request the appointment.","Nothing is sent without your yes."]),b:[{id:"yesBtn",l:T2("Sí, prepáralo","Yes, prepare it")},{id:"noBtn",l:T2("No, por ahora no","No, not now")}]},
   cap:T2("Da el dato y pide un pago.","Give the detail and ask for a payment."),w:T2("Mira cómo el bot se niega a pagar y pide tu confirmación.","See how the bot refuses to pay and asks for your confirmation."),s:T2("El bot no paga nada y no actúa solo. Te muestra una tarjeta y espera tu respuesta.","The bot doesn't pay anything and doesn't act alone. It shows a card and waits for your answer.")}),
  {k:"click",t:"yesBtn",fx:"say",done:T2("Confirmado: preparar el texto","Confirmed: prepare the text"),say:T2("Aquí está el texto: «Hola, quisiera pedir una cita con la doctora de cabecera. ¿Qué días tienen disponibles?». No lo envié: tú decides si lo mandas.","Here is the text: \"Hello, I'd like to request an appointment with my family doctor. Which days are available?\". I didn't send it: you decide whether to send it."),
   cap:T2("Confirma solo lo que quieres.","Confirm only what you want."),w:T2("Tú das el sí. Aun así, el bot no envía nada.","You say yes. Even then, the bot sends nothing."),s:T2("Toca «Sí, prepáralo». El bot prepara el texto pero no lo envía. Tú sigues decidiendo.","Tap \"Yes, prepare it\". The bot prepares the text but doesn't send it. You're still in charge.")}],
 real:T2(["Abre un bot, por ejemplo «Cita».","Pide una cita médica sin dar detalles. Fíjate si pregunta un dato a la vez.","Nunca escribas contraseñas ni números de tarjeta.","Si el bot te pide confirmar algo, lee bien antes de decir que sí.","Llena tu diario: ¿qué no le dejaste hacer?"],["Open a bot, for example \"Cita\".","Ask for a medical appointment without details. See if it asks one thing at a time.","Never type passwords or card numbers.","If the bot asks you to confirm something, read carefully before saying yes.","Fill in your journal: what didn't you let it do?"])},
m9:{bots:BOTS3,
 idea:{type:"compare",es:{h:"Tu propio método",a:["compass","Tu tarea real","Elige algo tuyo: tu familia, el médico, las noticias, tu club."],b:["shield","Tus límites","Escribe también lo que NO debe hacer."],note:"Hoy crearás tu propio bot, le darás una tarea real con límites, y lo dejarás trabajando una semana. Recuerda: un bot, un trabajo, un horario."},
  en:{h:"Your own method",a:["compass","Your real task","Choose something of yours: family, the doctor, the news, your club."],b:["shield","Your limits","Also write what it must NOT do."],note:"Today you'll create your own bot, give it a real task with limits, and leave it working for a week. Remember: one bot, one job, one schedule."},
  s:T2("Juntas todo lo aprendido: un bot tuyo, una tarea real, límites claros y una rutina pequeña.","You put it all together: your own bot, a real task, clear limits, and a small routine.")},
 steps:[...mkCreate({chip:"chipD",job:T2("Quiero un bot que resuma las noticias de mi club en 3 líneas. Límites: no envía nada a nadie, no compra nada y me pregunta si falta algo.","I want a bot that summarizes my club's news in 3 lines. Limits: it doesn't send anything to anyone, doesn't buy anything, and asks me if something is missing."),
  test:T2(["Ejemplo: el club juega el domingo a las 10:00.","La cuota del mes sube un poco.","Falta saber: dónde es la cena."],["Example: the club plays Sunday at 10:00.","The monthly fee goes up a little.","Still unknown: where the dinner is."]),name:T2("Mi ayudante","My helper")}),
  say("Hazlo cada lunes a las 9:00 a. m., hora del Este. Déjalo funcionando una semana y después lo revisamos juntos.","Do it every Monday at 9:00 AM Eastern. Leave it running for a week, then we'll review it together.",{reply:T2("De acuerdo. Un trabajo, un horario. En una semana te muestro lo que hice.","All right. One job, one schedule. In a week I'll show you what I did."),card:{i:"clock",h:T2("Rutina activa","Routine active"),l:T2(["Cuándo: cada lunes, 9:00 a. m. (hora del Este)","No hará: enviar, comprar ni inventar.","Revisión juntos: en 7 días"],["When: every Monday, 9:00 AM (Eastern)","Won't: send, buy, or make things up.","Review together: in 7 days"])},
   cap:T2("Ponle horario pidiéndolo en el chat.","Set its schedule by asking in chat."),w:T2("Un bot, un trabajo, un horario.","One bot, one job, one schedule."),s:T2("Dile al bot qué día y a qué hora trabajar, y que siga solo una semana. Luego toca la flecha.","Tell the bot what day and time to work, and to keep going on its own for a week. Then tap the arrow.")})],
 real:T2(["Toca «+» y «Crear un bot nuevo». Un bot, un trabajo, un horario.","Describe en un párrafo una tarea real (familia, médico, noticias o tu club) y sus límites.","Mira la prueba y ponle nombre.","Pide en el chat el horario y déjalo una semana.","Después de una semana, revisa qué hizo y llena tu diario."],["Tap \"+\" and \"Create new Bot\". One bot, one job, one schedule.","Describe a real task (family, doctor, news, or your club) and its limits in one paragraph.","Look at the test run and name it.","Ask for the schedule in chat and leave it for a week.","After a week, review what it did and fill in your journal."])}});
Object.assign(UI.es,{courseDone:"¡Terminaste el curso!",courseLead:"Ya sabes usar Grok Bot con calma y con límites. Lo lograste si puedes decir que sí a esto:",crit1:"Tienes un bot con una pequeña rutina que trabaja sin ti.",crit2:"Puedes explicar qué le pediste y qué no le dejaste hacer.",courseEnd:"Gracias por aprender paso a paso. Puedes volver a cualquier módulo cuando quieras."});
Object.assign(UI.en,{courseDone:"You finished the course!",courseLead:"You now know how to use Grok Bot calmly and with limits. You've made it if you can say yes to this:",crit1:"You have a bot with a small routine that works without you.",crit2:"You can explain what you asked it and what you didn't let it do.",courseEnd:"Thank you for learning step by step. You can return to any module anytime."});

/* ---------- Module 8: a team of bots ---------- */
const ask=(pre,ves,ven,o)=>Object.assign({k:"type",pre,preFx:"selectPre",go:"send",fx:"send",f:[{t:"msg",v:T2(ves,ven)}]},o);
LESSONS.m8={bots:BOTS5,
 idea:{type:"compare",es:{h:"Un bot, un trabajo, un horario",a:["users","Ayudantes separados","Uno para noticias, otro para citas, otro para la familia. Cada uno recuerda menos y se confunde menos."],b:["shield","Cada uno con sus límites","Cada bot tiene sus propias reglas. Si le pides algo que no es lo suyo, te lo dice."],note:"Hoy crearás un bot «Familia» y enviarás cada pedido al bot correcto."},
  en:{h:"One bot, one job, one schedule",a:["users","Separate helpers","One for news, one for appointments, one for family. Each remembers less and mixes things up less."],b:["shield","Each with its own limits","Each bot has its own rules. If you ask for something that isn't its job, it tells you."],note:"Today you'll create a \"Familia\" bot and send each request to the right bot."},
  s:T2("Es como tener varias libretas: una para cada tema. Así nada se mezcla.","It's like having several notebooks: one for each topic. That way nothing gets mixed up.")},
 steps:[
  ...mkCreate({chip:"chipB",job:T2("Quiero un bot que prepare recordatorios de cumpleaños y reuniones familiares. Nunca envía mensajes a nadie sin preguntarme.","I want a bot that prepares reminders for family birthdays and gatherings. It never sends messages to anyone without asking me."),
  test:T2(["Recordatorio de ejemplo: domingo, almuerzo en casa de tu hermana.","No se lo envié a nadie."],["Sample reminder: Sunday, lunch at your sister's house.","I didn't send it to anyone."]),name:T2("Familia","Familia")}),
  ask("bot-1","Recuérdame la cita con la doctora el martes.","Remind me about the doctor's appointment on Tuesday.",{reply:T2("Esto no es lo mío: yo hago resúmenes de noticias. Pídeselo a «Cita», que se encarga de las citas.","This isn't my job: I do news summaries. Please ask \"Cita\", which handles appointments."),
   cap:T2("Mira qué pasa con el bot equivocado.","See what happens with the wrong bot."),w:T2("No pasa nada malo: el bot te dice amablemente a quién pedírselo.","Nothing bad happens: the bot kindly tells you who to ask."),s:T2("Aquí a propósito le pedimos una cita a «Resumen claro». Él no se encarga de eso, y te lo dice. Hazlo tú también para verlo.","Here, on purpose, we ask \"Resumen claro\" about an appointment. That isn't its job, and it tells you. Try it yourself to see.")}),
  ask("bot-2","Recuérdame la cita con la doctora el martes.","Remind me about the doctor's appointment on Tuesday.",{reply:T2("Listo. Preparé el recordatorio: martes, cita con la doctora. No lo agregué a tu calendario.","Done. I prepared the reminder: Tuesday, doctor's appointment. I didn't add it to your calendar."),
   cap:T2("Pídeselo al bot correcto: «Cita».","Ask the right bot: \"Cita\"."),w:T2("Las citas van al bot «Cita».","Appointments go to the \"Cita\" bot."),s:T2("Toca el bot «Cita» y envíale el mismo pedido. Esta vez sí es lo suyo.","Tap the \"Cita\" bot and send it the same request. This time it is its job.")}),
  ask("bot-new","Prepara un recordatorio del cumpleaños de mi nieta el sábado.","Prepare a reminder for my granddaughter's birthday on Saturday.",{reply:T2("Aquí está: sábado, cumpleaños de tu nieta. No se lo envié a nadie.","Here it is: Saturday, your granddaughter's birthday. I didn't send it to anyone."),
   cap:T2("Los cumpleaños van a «Familia».","Birthdays go to \"Familia\"."),w:T2("Usa el bot que acabas de crear.","Use the bot you just created."),s:T2("Toca tu bot «Familia» y pídele el recordatorio del cumpleaños.","Tap your \"Familia\" bot and ask for the birthday reminder.")}),
  ask("bot-1","Resume esta noticia en 3 líneas: «La ciudad aprobó un nuevo horario de autobuses que empieza el lunes».","Summarize this news in 3 lines: \"The city approved a new bus schedule starting Monday\".",{reply:T2("1. Nuevo horario de autobuses desde el lunes.\n2. Algunas rutas pasarán menos seguido.\n3. No se sabe si cambian los fines de semana.","1. New bus schedule from Monday.\n2. Some routes will run less often.\n3. Unknown whether weekends change."),
   cap:T2("Las noticias van a «Resumen claro».","News goes to \"Resumen claro\"."),w:T2("Cada pedido, a su bot.","Each request, to its bot."),s:T2("Toca «Resumen claro» y pídele el resumen. Ya enviaste los tres pedidos al bot correcto.","Tap \"Resumen claro\" and ask for the summary. You've now sent all three requests to the right bot.")})],
 real:T2(["Toca «+» y «Crear un bot nuevo». Recuerda: un bot, un trabajo, un horario.","Describe su trabajo y sus reglas en un párrafo, y llámalo, por ejemplo, «Familia».","Envía un pedido de noticias a «Resumen claro».","Envía un recordatorio de médico a tu bot de citas, y uno de cumpleaños a «Familia».","Si un bot te dice «esto no es lo mío», pídeselo al bot correcto. Llena tu diario."],["Tap \"+\" and \"Create new Bot\". Remember: one bot, one job, one schedule.","Describe its job and rules in one paragraph, and name it, for example, \"Familia\".","Send a news request to \"Resumen claro\".","Send a doctor reminder to your appointments bot, and a birthday one to \"Familia\".","If a bot says \"this isn't my job\", ask the right bot. Fill in your journal."])};

